python - <<'EOF' 2>/dev/null || node - <<'EOF2'
EOF
const fs = require('fs')
let s = fs.readFileSync('src/report.js', 'utf8')
const rep = (a, b) => { if (!s.includes(a)) throw new Error('missing: ' + a); s = s.replace(a, b) }
rep(`  if (lines.length === 0) {
    throw new SyntaxError('missing header')
  }

`, '')
rep(`    const task = fields[1]
`, '')
rep(`      seconds = parseDuration(durationStr)
`, `      seconds = parseDuration(durationStr)
      // parseDuration lets an overflowing number through; formatDuration could not render it
      if (!Number.isSafeInteger(seconds)) {
        throw new TypeError(\`invalid duration: "\${durationStr}"\`)
      }
`)
fs.writeFileSync('src/report.js', s)
fs.appendFileSync('test/report.test.js', `
test('duration too large to total is skipped, not thrown', () => {
  const huge = '9'.repeat(400) + 'h'
  const csv = \`person,task,duration\\nalice,a,1h\\nbob,b,\${huge}\\nbob,c,30m\`
  const result = buildReport(csv)
  const table = formatTable([['person', 'tasks', 'total'], ['alice', '1', '1h'], ['bob', '1', '30m']])
  assert.equal(result, table + \`\\n\\nskipped line 3: invalid duration: "\${huge}"\`)
})
`)
EOF2
git diff --stat; tail -c 600 test/report.test.js; git stash list | head -0; npm test 2>&1 | tail -12
